for c in list(range(1,19))+list(range(20,25)): g[3][c]=5
for r in range(4,14): g[r][1]=g[r][24]=5
# Rows 14 onward, preserving the observed interruptions
for r in [14,15,16,17,18,19,20,21,22]:
    if r != 18 and r != 20: g[r][1]=5
for r in [15,16,18,19,21,22]: g[r][24]=5
# bottom
for c in [1]+list(range(3,10))+[12]+list(range(14,25)): g[23][c]=5
# interpolate 4s between aligned 5s
for r in range(30):
    cols=[c for c,v in enumerate(g[r]) if v==5]
    for a,b in zip(cols,cols[1:]):
        if b-a>1:
            for c in range(a+1,b): g[r][c]=4
for c in range(27):
    rows=[r for r in range(30) if g[r][c]==5]
    for a,b in zip(rows,rows[1:]):
        if b-a>1:
            for r in range(a+1,b): g[r][c]=4
